//! HDR histogram: frozen v1 parameters, bucket math, V2 wire codec, statistics.
//!
//! WM-0007 freezes the v1 recording parameters (2 significant figures, unit
//! nanoseconds, values 1..=1 hour) and pins the wire format by conformance
//! tests against reference blobs generated by HdrHistogram Java 2.2.2 and
//! hdrhistogram-go v1.4.0 (`tests/fixtures/hdr_conformance.json`, produced by
//! `tools/hdr_conformance/`). The percentile/mean semantics follow the Java
//! implementation (the canonical upstream); hdrhistogram-go truncates the
//! percentile target count instead of rounding up, a documented divergence
//! recorded in the fixture's `meta.percentile_rounding` — Rust follows Java.
//!
//! Scope: this module holds parameters, geometry/index math, the compressed
//! V2 blob codec and statistics over recorded counts. A live recorder around
//! it belongs to the worker runtime (Phase 3, WM-0317).
//!
//! Codec limitations: only `normalizingIndexOffset == 0` blobs decode (this
//! implementation never shifts); the compressed cookie must match exactly.

use std::io::{Read, Write};

/// Frozen v1 significant figures (WM-0007).
pub const HDR_SIG_FIGURES: u32 = 2;
/// Frozen v1 lowest discernible value (unit nanoseconds).
pub const HDR_LOWEST_DISCERNIBLE_VALUE: i64 = 1;
/// Frozen v1 highest trackable value: one hour in nanoseconds.
pub const HDR_HIGHEST_TRACKABLE_VALUE: i64 = 3_600_000_000_000;

/// V2 wire cookie for the zlib-compressed outer blob (HdrHistogram Java 2.2.2).
pub const V2_COMPRESSED_ENCODING_COOKIE: u32 = 0x1c84_9314;
/// V2 wire cookie for the uncompressed inner payload.
pub const V2_ENCODING_COOKIE: u32 = 0x1c84_9313;

const V2_HEADER_SIZE: usize = 40;
const V2_COMPRESSED_HEADER_SIZE: usize = 8;

#[derive(Debug, thiserror::Error)]
pub enum HdrError {
    #[error("invalid histogram parameters: {0}")]
    InvalidParameters(&'static str),
    #[error("value {value} outside covered range [0, {highest}]")]
    OutOfRange { value: i64, highest: i64 },
    #[error("count overflow at counts index {index}")]
    CountOverflow { index: usize },
    #[error("histogram parameters mismatch: expected {expected}, got {got}")]
    ParameterMismatch { expected: String, got: String },
    #[error("bad blob cookie 0x{got:08x}, expected 0x{expected:08x}")]
    BadCookie { got: u32, expected: u32 },
    #[error("blob truncated: {0}")]
    Truncated(&'static str),
    #[error("corrupt blob: {0}")]
    Corrupt(&'static str),
    #[error("unsupported blob feature: {0}")]
    Unsupported(&'static str),
    #[error("zlib: {0}")]
    Zlib(#[from] std::io::Error),
}

/// Recording parameters of one histogram (lowest, significant figures, highest).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HdrParameters {
    pub lowest_discernible_value: i64,
    pub significant_figures: u32,
    pub highest_trackable_value: i64,
}

/// Derived bucket layout for a parameter set (HdrHistogram geometry).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct HdrGeometry {
    pub largest_value_with_single_unit_resolution: i64,
    pub sub_bucket_count: i64,
    pub sub_bucket_half_count: i64,
    pub sub_bucket_half_count_magnitude: u32,
    pub unit_magnitude: u32,
    pub bucket_count: u32,
    pub counts_len: usize,
}

impl HdrParameters {
    /// The frozen v1 parameters (WM-0007): ns unit, 2 sig figs, 1h max.
    pub const fn frozen_v1() -> Self {
        Self {
            lowest_discernible_value: HDR_LOWEST_DISCERNIBLE_VALUE,
            significant_figures: HDR_SIG_FIGURES,
            highest_trackable_value: HDR_HIGHEST_TRACKABLE_VALUE,
        }
    }

    pub fn new(lowest: i64, significant_figures: u32, highest: i64) -> Result<Self, HdrError> {
        let params = Self {
            lowest_discernible_value: lowest,
            significant_figures,
            highest_trackable_value: highest,
        };
        params.geometry()?;
        Ok(params)
    }

    /// Derive the bucket layout. Mirrors HdrHistogram's
    /// `initBucketSubBucketInformation` + `determineArrayLengthNeeded`
    /// (validated against the Java/Go reference matrices in the fixture).
    pub fn geometry(&self) -> Result<HdrGeometry, HdrError> {
        let lowest = self.lowest_discernible_value;
        let highest = self.highest_trackable_value;
        if lowest < 1 {
            return Err(HdrError::InvalidParameters(
                "lowestDiscernibleValue must be >= 1",
            ));
        }
        if self.significant_figures > 5 {
            return Err(HdrError::InvalidParameters(
                "significantFigures must be <= 5",
            ));
        }
        if highest < lowest {
            return Err(HdrError::InvalidParameters(
                "highestTrackableValue must be >= lowestDiscernibleValue",
            ));
        }
        let largest = 2 * 10i64
            .checked_pow(self.significant_figures)
            .ok_or(HdrError::InvalidParameters("significantFigures too large"))?;
        // ceil(log2(largest)): bits needed for largest - 1.
        let sub_bucket_magnitude = 64 - ((largest - 1) as u64).leading_zeros();
        let half_magnitude = sub_bucket_magnitude - 1;
        let unit_magnitude = 63 - (lowest as u64).leading_zeros();
        // Java rejects layouts whose sub-bucket range cannot fit a positive long.
        if half_magnitude + 1 + unit_magnitude > 62 {
            return Err(HdrError::InvalidParameters(
                "sub-bucket range not representable in i64",
            ));
        }
        let half_count = 1i64 << half_magnitude;
        let sub_bucket_count = half_count << 1;
        if (sub_bucket_count as u64).leading_zeros() <= unit_magnitude {
            return Err(HdrError::InvalidParameters(
                "smallest untrackable value overflows i64",
            ));
        }
        let mut smallest_untrackable = sub_bucket_count << unit_magnitude;
        let mut bucket_count = 1u32;
        while smallest_untrackable <= highest {
            if smallest_untrackable > i64::MAX / 2 {
                bucket_count += 1;
                break;
            }
            smallest_untrackable <<= 1;
            bucket_count += 1;
        }
        let counts_len = ((bucket_count as i64 + 1) * half_count) as usize;
        Ok(HdrGeometry {
            largest_value_with_single_unit_resolution: largest,
            sub_bucket_count,
            sub_bucket_half_count: half_count,
            sub_bucket_half_count_magnitude: half_magnitude,
            unit_magnitude,
            bucket_count,
            counts_len,
        })
    }
}

impl HdrGeometry {
    fn sub_bucket_mask(&self) -> i64 {
        (self.sub_bucket_count - 1) << self.unit_magnitude
    }

    /// The bucket holding `value` (HdrHistogram `getBucketIndex`).
    pub fn bucket_index_of(&self, value: i64) -> u32 {
        let lzc_base = 64 - self.unit_magnitude - (self.sub_bucket_half_count_magnitude + 1);
        lzc_base - ((value | self.sub_bucket_mask()) as u64).leading_zeros()
    }

    /// Position of `value` within its bucket (HdrHistogram `getSubBucketIndex`).
    pub fn sub_bucket_index_of(&self, value: i64, bucket: u32) -> i64 {
        value >> (bucket + self.unit_magnitude)
    }

    /// Counts-array slot for `value` (HdrHistogram `countsArrayIndex`).
    pub fn counts_index_for(&self, value: i64) -> usize {
        let bucket = self.bucket_index_of(value);
        let sub = self.sub_bucket_index_of(value, bucket);
        let base = (bucket as i64 + 1) << self.sub_bucket_half_count_magnitude;
        (base + (sub - self.sub_bucket_half_count)) as usize
    }

    /// Value at the start of a counts slot (HdrHistogram `valueFromIndex`).
    pub fn value_from_index(&self, index: usize) -> i64 {
        let half = self.sub_bucket_half_count;
        let mut bucket = ((index >> self.sub_bucket_half_count_magnitude) as i64) - 1;
        let mut sub = ((index as i64) & (half - 1)) + half;
        if bucket < 0 {
            sub -= half;
            bucket = 0;
        }
        sub << (bucket + self.unit_magnitude as i64)
    }

    /// Width of the equivalence interval around `value`.
    pub fn size_of_equivalent_value_range(&self, value: i64) -> i64 {
        1i64 << (self.bucket_index_of(value) + self.unit_magnitude)
    }

    pub fn lowest_equivalent_value(&self, value: i64) -> i64 {
        let bucket = self.bucket_index_of(value);
        self.sub_bucket_index_of(value, bucket) << (bucket + self.unit_magnitude)
    }

    pub fn highest_equivalent_value(&self, value: i64) -> i64 {
        self.lowest_equivalent_value(value) + self.size_of_equivalent_value_range(value) - 1
    }

    pub fn median_equivalent_value(&self, value: i64) -> i64 {
        self.lowest_equivalent_value(value) + (self.size_of_equivalent_value_range(value) >> 1)
    }
}

/// A recorded histogram: counts array plus the stats trackers.
#[derive(Debug, Clone)]
pub struct Histogram {
    params: HdrParameters,
    geometry: HdrGeometry,
    counts: Vec<i64>,
    total_count: i64,
    max_value: i64,
    min_non_zero_index: Option<usize>,
}

impl Histogram {
    pub fn new(params: HdrParameters) -> Result<Self, HdrError> {
        let geometry = params.geometry()?;
        Ok(Self {
            params,
            counts: vec![0; geometry.counts_len],
            total_count: 0,
            max_value: 0,
            min_non_zero_index: None,
            geometry,
        })
    }

    pub fn params(&self) -> HdrParameters {
        self.params
    }

    pub fn geometry(&self) -> HdrGeometry {
        self.geometry
    }

    pub fn counts(&self) -> &[i64] {
        &self.counts
    }

    pub fn total_count(&self) -> i64 {
        self.total_count
    }

    /// Record one occurrence of `value`.
    pub fn record_value(&mut self, value: i64) -> Result<(), HdrError> {
        self.record_value_count(value, 1)
    }

    pub fn record_value_count(&mut self, value: i64, count: i64) -> Result<(), HdrError> {
        if value < 0 || value > self.params.highest_trackable_value {
            return Err(HdrError::OutOfRange {
                value,
                highest: self.params.highest_trackable_value,
            });
        }
        let index = self.geometry.counts_index_for(value);
        let slot = self.counts[index]
            .checked_add(count)
            .ok_or(HdrError::CountOverflow { index })?;
        let total = self
            .total_count
            .checked_add(count)
            .ok_or(HdrError::CountOverflow { index })?;
        self.counts[index] = slot;
        self.total_count = total;
        if value > self.max_value {
            self.max_value = value;
        }
        if index != 0 && self.min_non_zero_index.is_none_or(|m| index < m) {
            self.min_non_zero_index = Some(index);
        }
        Ok(())
    }

    /// Counts-level merge (`add` in HdrHistogram terms): fold `other`
    /// into `self` slot by slot. This is the ONLY honest way to
    /// aggregate distributions — percentiles of the merged histogram
    /// come from merged raw counts, never from averaging per-source
    /// percentiles. Parameters must be IDENTICAL (v1 freezes one
    /// parameter set globally, so workers can always merge); anything
    /// else is refused by name, not approximated.
    pub fn merge_from(&mut self, other: &Histogram) -> Result<(), HdrError> {
        if self.params != other.params {
            return Err(HdrError::ParameterMismatch {
                expected: format!(
                    "lowest={}, sig_figs={}, highest={}",
                    self.params.lowest_discernible_value,
                    self.params.significant_figures,
                    self.params.highest_trackable_value,
                ),
                got: format!(
                    "lowest={}, sig_figs={}, highest={}",
                    other.params.lowest_discernible_value,
                    other.params.significant_figures,
                    other.params.highest_trackable_value,
                ),
            });
        }
        // Check the total overflow BEFORE touching any slot so a
        // failed merge leaves self untouched.
        let total = self
            .total_count
            .checked_add(other.total_count)
            .ok_or(HdrError::CountOverflow { index: 0 })?;
        for (index, &count) in other.counts.iter().enumerate() {
            if count == 0 {
                continue;
            }
            let slot = self.counts[index]
                .checked_add(count)
                .ok_or(HdrError::CountOverflow { index })?;
            self.counts[index] = slot;
            let value = self.geometry.value_from_index(index);
            if value > self.max_value {
                self.max_value = value;
            }
            if index != 0 && self.min_non_zero_index.is_none_or(|m| index < m) {
                self.min_non_zero_index = Some(index);
            }
        }
        self.total_count = total;
        Ok(())
    }

    /// HdrHistogram `getMinValue`: 0 when empty or when any 0 was recorded.
    pub fn min_value(&self) -> i64 {
        if self.total_count == 0 || self.counts[0] > 0 {
            return 0;
        }
        let index = self
            .min_non_zero_index
            .expect("nonempty histogram without zero-slot counts has a nonzero slot");
        self.geometry
            .lowest_equivalent_value(self.geometry.value_from_index(index))
    }

    /// HdrHistogram `getMaxValue`: the highest value equivalent to the max record.
    pub fn max_value(&self) -> i64 {
        if self.max_value == 0 {
            0
        } else {
            self.geometry.highest_equivalent_value(self.max_value)
        }
    }

    /// HdrHistogram `getMean`: count-weighted median-equivalent values.
    pub fn mean(&self) -> f64 {
        if self.total_count == 0 {
            return 0.0;
        }
        let mut total_value = 0.0f64;
        for (index, &count) in self.counts.iter().enumerate() {
            if count > 0 {
                let value = self.geometry.value_from_index(index);
                total_value += self.geometry.median_equivalent_value(value) as f64 * count as f64;
            }
        }
        total_value / self.total_count as f64
    }

    /// HdrHistogram `getValueAtPercentile` (Java semantics: 1-ulp-low target,
    /// ceil, clamp at 1; equivalence-interval bounds at the reached slot).
    pub fn value_at_percentile(&self, percentile: f64) -> i64 {
        let requested = next_after_down(percentile).clamp(0.0, 100.0);
        let target = (((requested * self.total_count as f64) / 100.0).ceil() as i64).max(1);
        let mut running = 0i64;
        for (index, &count) in self.counts.iter().enumerate() {
            running += count;
            if running >= target {
                let value = self.geometry.value_from_index(index);
                return if percentile == 0.0 {
                    self.geometry.lowest_equivalent_value(value)
                } else {
                    self.geometry.highest_equivalent_value(value)
                };
            }
        }
        0
    }

    /// Encode as a compressed V2 blob (zlib around the 40-byte inner header
    /// plus a zigzag LEB128-64b9B counts stream; payload truncated at the max
    /// value's slot, Java `fillBufferFromCountsArray` policy).
    pub fn encode_v2_blob(&self) -> Result<Vec<u8>, HdrError> {
        let counts = self.encode_counts_stream()?;
        let mut inner = Vec::with_capacity(V2_HEADER_SIZE + counts.len());
        inner.extend_from_slice(&V2_ENCODING_COOKIE.to_be_bytes());
        inner.extend_from_slice(&(counts.len() as i32).to_be_bytes());
        inner.extend_from_slice(&0i32.to_be_bytes()); // normalizingIndexOffset
        inner.extend_from_slice(&(self.params.significant_figures as i32).to_be_bytes());
        inner.extend_from_slice(&self.params.lowest_discernible_value.to_be_bytes());
        inner.extend_from_slice(&self.params.highest_trackable_value.to_be_bytes());
        inner.extend_from_slice(&1.0f64.to_be_bytes()); // int->double ratio
        inner.extend_from_slice(&counts);

        let mut encoder =
            flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
        encoder.write_all(&inner)?;
        let deflated = encoder.finish()?;

        let mut blob = Vec::with_capacity(V2_COMPRESSED_HEADER_SIZE + deflated.len());
        blob.extend_from_slice(&V2_COMPRESSED_ENCODING_COOKIE.to_be_bytes());
        blob.extend_from_slice(&(deflated.len() as i32).to_be_bytes());
        blob.extend_from_slice(&deflated);
        Ok(blob)
    }

    /// Decode a compressed V2 blob written by this implementation, HdrHistogram
    /// Java, or hdrhistogram-go (identical wire layout; cookies and geometry
    /// re-derived from the blob header).
    pub fn decode_v2_blob(blob: &[u8]) -> Result<Self, HdrError> {
        if blob.len() < V2_COMPRESSED_HEADER_SIZE {
            return Err(HdrError::Truncated("compressed header"));
        }
        let cookie = u32::from_be_bytes(blob[0..4].try_into().expect("4 bytes"));
        if cookie != V2_COMPRESSED_ENCODING_COOKIE {
            return Err(HdrError::BadCookie {
                got: cookie,
                expected: V2_COMPRESSED_ENCODING_COOKIE,
            });
        }
        let compressed_len = i32::from_be_bytes(blob[4..8].try_into().expect("4 bytes"));
        if compressed_len < 0 {
            return Err(HdrError::Corrupt("negative compressed length"));
        }
        let compressed_len = compressed_len as usize;
        if blob.len() - V2_COMPRESSED_HEADER_SIZE < compressed_len {
            return Err(HdrError::Truncated("compressed payload"));
        }
        let mut decoder = flate2::read::ZlibDecoder::new(
            &blob[V2_COMPRESSED_HEADER_SIZE..V2_COMPRESSED_HEADER_SIZE + compressed_len],
        );
        let mut inner = Vec::new();
        decoder.read_to_end(&mut inner)?;
        if inner.len() < V2_HEADER_SIZE {
            return Err(HdrError::Truncated("inner header"));
        }

        let inner_cookie = u32::from_be_bytes(inner[0..4].try_into().expect("4 bytes"));
        if inner_cookie != V2_ENCODING_COOKIE {
            return Err(HdrError::BadCookie {
                got: inner_cookie,
                expected: V2_ENCODING_COOKIE,
            });
        }
        let payload_len = i32::from_be_bytes(inner[4..8].try_into().expect("4 bytes"));
        if payload_len < 0 {
            return Err(HdrError::Corrupt("negative payload length"));
        }
        let payload_len = payload_len as usize;
        if inner.len() - V2_HEADER_SIZE < payload_len {
            return Err(HdrError::Truncated("counts payload"));
        }
        let normalizing_offset = i32::from_be_bytes(inner[8..12].try_into().expect("4 bytes"));
        if normalizing_offset != 0 {
            return Err(HdrError::Unsupported("nonzero normalizingIndexOffset"));
        }
        let significant_figures = i32::from_be_bytes(inner[12..16].try_into().expect("4 bytes"));
        if !(0..=5).contains(&significant_figures) {
            return Err(HdrError::Corrupt("significant figures out of range"));
        }
        let lowest = i64::from_be_bytes(inner[16..24].try_into().expect("8 bytes"));
        let highest = i64::from_be_bytes(inner[24..32].try_into().expect("8 bytes"));
        // inner[32..40] is the int->double ratio; int histograms always write 1.0.

        let params = HdrParameters::new(lowest, significant_figures as u32, highest)?;
        let geometry = params.geometry()?;
        let mut counts = vec![0i64; geometry.counts_len];
        let end = V2_HEADER_SIZE + payload_len;
        let mut pos = V2_HEADER_SIZE;
        let mut index = 0usize;
        while pos < end {
            let value = zigzag_get(&inner, &mut pos)
                .ok_or(HdrError::Truncated("varint inside counts payload"))?;
            if value < 0 {
                let run = value
                    .checked_neg()
                    .ok_or(HdrError::Corrupt("zero run overflow"))?;
                index += run as usize;
                if index > geometry.counts_len {
                    return Err(HdrError::Corrupt("zero run overruns counts array"));
                }
            } else {
                if index >= geometry.counts_len {
                    return Err(HdrError::Corrupt("count overruns counts array"));
                }
                counts[index] = value;
                index += 1;
            }
        }

        let mut total_count = 0i64;
        let mut max_value = 0i64;
        let mut min_non_zero_index = None;
        for (i, &count) in counts.iter().enumerate() {
            if count > 0 {
                total_count = total_count
                    .checked_add(count)
                    .ok_or(HdrError::Corrupt("counts sum overflows i64"))?;
                max_value = geometry.value_from_index(i);
                if i != 0 && min_non_zero_index.is_none() {
                    min_non_zero_index = Some(i);
                }
            }
        }
        Ok(Self {
            params,
            geometry,
            counts,
            total_count,
            max_value,
            min_non_zero_index,
        })
    }

    fn encode_counts_stream(&self) -> Result<Vec<u8>, HdrError> {
        // Payload is truncated at the max value's slot like Java's encoder;
        // an empty histogram still emits its (zero) slot 0.
        let limit = if self.total_count == 0 {
            1
        } else {
            self.geometry.counts_index_for(self.max_value) + 1
        };
        let mut out = Vec::new();
        let mut index = 0usize;
        while index < limit {
            let count = self.counts[index];
            index += 1;
            let mut zeros = 0i64;
            if count == 0 {
                zeros = 1;
                while index < limit && self.counts[index] == 0 {
                    zeros += 1;
                    index += 1;
                }
            }
            if zeros > 1 {
                zigzag_put(&mut out, -zeros);
            } else {
                zigzag_put(&mut out, count);
            }
        }
        Ok(out)
    }
}

/// Largest double strictly below `x` (Java `Math.nextAfter(x, -inf)`); values
/// at or below 0 pass through and are clamped by the caller.
fn next_after_down(x: f64) -> f64 {
    if x.is_nan() || x <= 0.0 {
        return x;
    }
    f64::from_bits(x.to_bits() - 1)
}

/// ZigZag LEB128-64b9B encode (HdrHistogram ZigZagEncoding.putLong): bytes
/// 1..8 carry seven payload bits each plus a continuation bit; the ninth
/// byte carries the remaining bits (up to eight) without a continuation bit.
fn zigzag_put(buf: &mut Vec<u8>, value: i64) {
    let mut v = (value.wrapping_shl(1) ^ (value >> 63)) as u64;
    let mut pushed = 0usize;
    while v > 0x7F && pushed < 8 {
        buf.push(((v & 0x7F) as u8) | 0x80);
        v >>= 7;
        pushed += 1;
    }
    buf.push(v as u8);
}

/// ZigZag LEB128-64b9B decode (HdrHistogram ZigZagEncoding.getLong).
fn zigzag_get(data: &[u8], pos: &mut usize) -> Option<i64> {
    let mut byte = *data.get(*pos)?;
    *pos += 1;
    let mut value = (byte & 0x7F) as u64;
    let mut shift = 7u32;
    while byte & 0x80 != 0 {
        byte = *data.get(*pos)?;
        *pos += 1;
        if shift == 56 {
            // Ninth byte carries the final eight payload bits untagged; the
            // 64-bit value is complete there, so its top bit is data, not a
            // continuation flag.
            value |= (byte as u64) << 56;
            break;
        }
        value |= ((byte & 0x7F) as u64) << shift;
        shift += 7;
    }
    let sign = (value & 1).wrapping_neg();
    Some(((value >> 1) ^ sign) as i64)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn zigzag_roundtrips_extremes() {
        let values = [
            0i64,
            1,
            -1,
            63,
            64,
            -64,
            8191,
            -8192,
            16383,
            -16384,
            3_600_000_000_000,
            -4608,
            i64::MAX,
            i64::MIN,
        ];
        for value in values {
            let mut buf = Vec::new();
            zigzag_put(&mut buf, value);
            assert!(buf.len() <= 9, "{value} encoded in {} bytes", buf.len());
            let mut pos = 0usize;
            assert_eq!(zigzag_get(&buf, &mut pos), Some(value));
            assert_eq!(pos, buf.len());
        }
    }

    #[test]
    fn frozen_v1_geometry() {
        let geometry = HdrParameters::frozen_v1().geometry().unwrap();
        assert_eq!(geometry.largest_value_with_single_unit_resolution, 200);
        assert_eq!(geometry.sub_bucket_count, 256);
        assert_eq!(geometry.sub_bucket_half_count, 128);
        assert_eq!(geometry.sub_bucket_half_count_magnitude, 7);
        assert_eq!(geometry.unit_magnitude, 0);
        assert_eq!(geometry.bucket_count, 35);
        assert_eq!(geometry.counts_len, 4608);
    }

    #[test]
    fn rejects_invalid_parameters() {
        assert!(HdrParameters::new(0, 2, 100).is_err());
        assert!(HdrParameters::new(1, 6, 100).is_err());
        assert!(HdrParameters::new(100, 2, 1).is_err());
    }

    #[test]
    fn merge_is_counts_level_addition_with_identical_parameters_required() {
        // Worker A records low latencies, worker B records high ones.
        let mut a = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        for value in [1_000_000, 1_000_000, 2_000_000] {
            a.record_value(value).unwrap();
        }
        let mut b = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        for value in [9_000_000_000, 9_000_000_000, 3_600_000_000_000] {
            b.record_value(value).unwrap();
        }
        a.merge_from(&b).expect("identical params merge");
        assert_eq!(a.total_count(), 6);
        assert_eq!(a.max_value(), b.max_value(), "max travels with the merge");
        // Percentiles of the merged histogram come from merged counts:
        // the low half and high half each hold 3 of 6 samples, so the
        // median sits at the boundary between the two clusters — NOT
        // an average of the two per-worker medians.
        let median = a.value_at_percentile(50.0);
        assert!(
            (2_000_000..9_000_000_000).contains(&median),
            "median {median} must land in the merged count structure"
        );
        assert_eq!(a.value_at_percentile(100.0), b.value_at_percentile(100.0));

        // Different parameters are refused by name, never approximated.
        let mut other_params = Histogram::new(HdrParameters::new(1, 3, 1000).unwrap()).unwrap();
        other_params.record_value(10).unwrap();
        let mut target = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        assert!(matches!(
            target.merge_from(&other_params),
            Err(HdrError::ParameterMismatch { .. })
        ));
        assert_eq!(target.total_count(), 0, "refused merge leaves no trace");
    }

    #[test]
    fn merging_an_empty_histogram_is_the_honest_identity() {
        let mut a = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        a.record_value(5_000_000).unwrap();
        let empty = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        let before_max = a.max_value();
        a.merge_from(&empty).expect("identity merge");
        assert_eq!(a.total_count(), 1);
        assert_eq!(a.max_value(), before_max);
        let mut empty_target = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        empty_target.merge_from(&a).expect("empty absorbs");
        assert_eq!(empty_target.total_count(), 1);
        assert_eq!(empty_target.value_at_percentile(100.0), a.value_at_percentile(100.0));
    }

    #[test]
    fn record_and_stats_basics() {
        let mut histogram = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        for value in [0, 1, 2, 3, 1000] {
            histogram.record_value(value).unwrap();
        }
        assert_eq!(histogram.total_count(), 5);
        assert_eq!(histogram.min_value(), 0);
        assert_eq!(histogram.max_value(), 1003); // highest equivalent of 1000
        assert_eq!(histogram.value_at_percentile(50.0), 2);
        assert_eq!(histogram.value_at_percentile(100.0), 1003);
        assert_eq!(histogram.value_at_percentile(0.0), 0);
    }

    #[test]
    fn record_out_of_range_rejected() {
        let mut histogram = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        assert!(matches!(
            histogram.record_value(-1),
            Err(HdrError::OutOfRange { value: -1, .. })
        ));
        assert!(matches!(
            histogram.record_value(3_600_000_000_001),
            Err(HdrError::OutOfRange { .. })
        ));
        assert_eq!(histogram.total_count(), 0);
    }

    #[test]
    fn min_without_zero_records_uses_lowest_equivalent() {
        let mut histogram = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        histogram.record_value(1000).unwrap();
        histogram.record_value(1010).unwrap();
        // Both land in bucket 2 (values 512..1023): slot base of 1000 is 1000,
        // of 1010 is 1008; the equivalence interval is 4 wide.
        assert_eq!(histogram.min_value(), 1000);
        assert_eq!(histogram.max_value(), 1011);
    }

    #[test]
    fn blob_roundtrip_preserves_counts() {
        let mut histogram = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        let values = [1, 2, 255, 256, 257, 1000, 1_000_000, 3_600_000_000_000];
        for value in values {
            histogram.record_value(value).unwrap();
        }
        let blob = histogram.encode_v2_blob().unwrap();
        let decoded = Histogram::decode_v2_blob(&blob).unwrap();
        assert_eq!(decoded.counts(), histogram.counts());
        assert_eq!(decoded.total_count(), histogram.total_count());
        assert_eq!(decoded.max_value(), histogram.max_value());
        assert_eq!(
            decoded.value_at_percentile(99.0),
            histogram.value_at_percentile(99.0)
        );
        // Re-encoding the decoded histogram must remain stable.
        let blob2 = decoded.encode_v2_blob().unwrap();
        let decoded2 = Histogram::decode_v2_blob(&blob2).unwrap();
        assert_eq!(decoded2.counts(), histogram.counts());
    }

    #[test]
    fn empty_histogram_blob_roundtrip() {
        let histogram = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        let blob = histogram.encode_v2_blob().unwrap();
        let decoded = Histogram::decode_v2_blob(&blob).unwrap();
        assert_eq!(decoded.total_count(), 0);
        assert_eq!(decoded.min_value(), 0);
        assert_eq!(decoded.max_value(), 0);
        assert_eq!(decoded.value_at_percentile(50.0), 0);
    }

    #[test]
    fn decode_rejects_corrupt_blobs() {
        let histogram = Histogram::new(HdrParameters::frozen_v1()).unwrap();
        let blob = histogram.encode_v2_blob().unwrap();

        let mut bad_cookie = blob.clone();
        bad_cookie[0] = 0x12;
        assert!(matches!(
            Histogram::decode_v2_blob(&bad_cookie),
            Err(HdrError::BadCookie { .. })
        ));

        assert!(matches!(
            Histogram::decode_v2_blob(&blob[..4]),
            Err(HdrError::Truncated(_))
        ));
        assert!(matches!(
            Histogram::decode_v2_blob(&[]),
            Err(HdrError::Truncated(_))
        ));

        let mut truncated_payload = blob.clone();
        let last = truncated_payload.len() - 1;
        truncated_payload[last] ^= 0xFF;
        // Flipping zlib bytes fails either on inflate or on the cookie/length.
        assert!(Histogram::decode_v2_blob(&truncated_payload).is_err());

        // Forging the compressed length to exceed the actual payload must
        // surface as truncation, not a panic.
        let forged = blob[..blob.len() - 1].to_vec();
        let compressed_len = i32::from_be_bytes(forged[4..8].try_into().unwrap()) as usize;
        if forged.len() - V2_COMPRESSED_HEADER_SIZE < compressed_len {
            assert!(matches!(
                Histogram::decode_v2_blob(&forged),
                Err(HdrError::Truncated(_))
            ));
        }
    }

    #[test]
    fn decode_rejects_unsupported_normalizing_offset() {
        // A blob with nonzero normalizingIndexOffset cannot be produced by the
        // encoder; assert the decoder's guard via a hand-built inner header.
        let mut inner = Vec::new();
        inner.extend_from_slice(&V2_ENCODING_COOKIE.to_be_bytes());
        inner.extend_from_slice(&0i32.to_be_bytes());
        inner.extend_from_slice(&1i32.to_be_bytes()); // nonzero offset
        inner.extend_from_slice(&2i32.to_be_bytes());
        inner.extend_from_slice(&1i64.to_be_bytes());
        inner.extend_from_slice(&1_000_000i64.to_be_bytes());
        inner.extend_from_slice(&1.0f64.to_be_bytes());
        let mut encoder =
            flate2::write::ZlibEncoder::new(Vec::new(), flate2::Compression::default());
        encoder.write_all(&inner).unwrap();
        let deflated = encoder.finish().unwrap();
        let mut blob = Vec::new();
        blob.extend_from_slice(&V2_COMPRESSED_ENCODING_COOKIE.to_be_bytes());
        blob.extend_from_slice(&(deflated.len() as i32).to_be_bytes());
        blob.extend_from_slice(&deflated);
        assert!(matches!(
            Histogram::decode_v2_blob(&blob),
            Err(HdrError::Unsupported(_))
        ));
    }
}
